H="$HOME/stand-in-python"; mkdir -p "$H"
REALPY=$(PATH="${PATH#*:}" command -v python3)
cat > "$H/tokenizers.py" <<'EOF_0'
import hashlib
class _Encoded:
    def __init__(self, ids, mask): self.ids = ids; self.attention_mask = mask
class Tokenizer:
    @classmethod
    def from_file(cls, path): return cls()
    def enable_truncation(self, length): self.length = length
    def enable_padding(self, length, pad_id): self.pad = pad_id
    def encode_batch(self, texts):
        out = []
        for text in texts:
            ids = [49406] + [int.from_bytes(hashlib.sha256(w.lower().encode()).digest()[:4], 'big') % 49000 for w in text.split()] + [49407]
            ids = ids[:self.length]; mask = [1] * len(ids)
            out.append(_Encoded(ids + [self.pad] * (self.length - len(ids)), mask + [0] * (self.length - len(ids))))
        return out
EOF_0
cat > "$H/onnxmini.py" <<'EOF_1'
import numpy as np
def v(n):
    o = b''
    while True:
        b = n & 0x7f; n >>= 7
        if n: o += bytes([b | 0x80])
        else: return o + bytes([b])
def ln(k, d): return v(k << 3 | 2) + v(len(d)) + d
def i(k, n): return v(k << 3) + v(n)
def s(k, t): return ln(k, t.encode())
def tensor(name, dims, kind, raw): return b''.join(i(1, d) for d in dims) + i(2, kind) + s(8, name) + ln(9, raw)
def node(op, ins, outs, attrs=()): return b''.join(s(1, x) for x in ins) + b''.join(s(2, x) for x in outs) + s(4, op) + b''.join(ln(5, a) for a in attrs)
def info(name, kind, dims): return s(1, name) + ln(2, ln(1, i(1, kind) + ln(2, b''.join(ln(1, i(1, d) if isinstance(d, int) else s(2, d)) for d in dims))))
def model(nodes, inits, ins, outs):
    g = b''.join(ln(1, n) for n in nodes) + s(2, 'g') + b''.join(ln(5, t) for t in inits) + b''.join(ln(11, x) for x in ins) + b''.join(ln(12, x) for x in outs)
    return i(1, 7) + s(2, 'sample') + ln(7, g) + ln(8, s(1, '') + i(2, 13))
def weights(name, rows, cols, seed): return tensor(name, [rows, cols], 1, np.random.default_rng(seed).random((rows, cols)).astype('float32').tobytes())
def zeros(out, shape, ins):
    value = s(1, 'value') + ln(5, tensor('', [1], 1, np.zeros(1, 'float32').tobytes())) + i(20, 4)
    return node('ConstantOfShape', [out + '_shape'], [out], [value]), tensor(out + '_shape', [len(shape)], 7, np.array(shape, 'int64').tobytes())
EOF_1
cat > "$H/make_models.py" <<'EOF_2'
import os, sys
H = sys.argv[1]
sys.path.insert(0, H)

import json
from onnxmini import *
folder = os.path.join(H, 'clip')
os.makedirs(folder, exist_ok=True)
open(os.path.join(folder, 'tokenizer.json'), 'w').write('{}')
json.dump({'names': {'name': 'ViT-B-32', 'pretrained': 'stand-in'}, 'context_length': 77, 'pad_id': 49407}, open(os.path.join(folder, 'model.json'), 'w'))
open(os.path.join(folder, 'text_model.onnx'), 'wb').write(model(
    [node('Cast', ['input_ids'], ['as_numbers'], [s(1, 'to') + i(3, 1) + i(20, 2)]), node('MatMul', ['as_numbers', 'W'], ['text_embeds'])],
    [weights('W', 77, 512, 3)], [info('input_ids', 7, ['N', 77])], [info('text_embeds', 1, ['N', 512])]))
EOF_2
"$REALPY" "$H/make_models.py" "$H"
export PYTHONPATH="$H" PICTURE_WORDS_MODEL="$H/clip"
exec "$REALPY" "$@"
